package mx.com.mesaregia.inventario.application.service.impl;
import mx.com.mesaregia.inventario.application.service.EntradaInventarioService; import mx.com.mesaregia.inventario.api.request.EntradaInventarioRequest; import mx.com.mesaregia.inventario.api.response.MovimientoResponse; import mx.com.mesaregia.inventario.domain.entity.Existencia; import mx.com.mesaregia.inventario.domain.enums.*; import mx.com.mesaregia.inventario.exception.BusinessRuleException; import mx.com.mesaregia.inventario.mapper.InventarioMapper; import mx.com.mesaregia.inventario.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service
public class EntradaInventarioServiceImpl implements EntradaInventarioService {
 private final InventorySupport support; private final ExistenciaRepository er; private final MovimientoInventarioRepository mr; public EntradaInventarioServiceImpl(InventorySupport s,ExistenciaRepository e,MovimientoInventarioRepository m){support=s;er=e;mr=m;}
 @Override @Transactional public MovimientoResponse registrar(String key, EntradaInventarioRequest q){ if(q.origenOperacion()!=OrigenOperacion.CARGA_INICIAL&&q.origenOperacion()!=OrigenOperacion.REINGRESO) throw new BusinessRuleException("El origen de entrada debe ser CARGA_INICIAL o REINGRESO"); if(q.origenOperacion()==OrigenOperacion.REINGRESO&&q.idOrdenExterno()==null) throw new BusinessRuleException("La Orden es obligatoria para REINGRESO"); String op=support.operationKey(key,"ENTRADA|"+q.idAlmacen()+"|"+q.idProducto()); var prev=mr.findByClaveOperacion(op); if(prev.isPresent()) return InventarioMapper.movimiento(prev.get()); var e=er.findForUpdate(q.idAlmacen(),q.idProducto()).orElse(null); if(e==null){e=new Existencia();e.setAlmacen(support.almacen(q.idAlmacen()));e.setIdProductoExterno(q.idProducto());e.setExistenciaFisica(0); e=er.saveAndFlush(e);} int antes=e.getExistenciaFisica(); e.setExistenciaFisica(Math.addExact(antes,q.cantidad())); er.saveAndFlush(e); return InventarioMapper.movimiento(support.movimiento(e,TipoMovimiento.ENTRADA,q.origenOperacion(),q.cantidad(),antes,e.getExistenciaFisica(),q.idOrdenExterno(),null,null,q.comentario(),q.idUsuarioExterno(),op)); }
}
